xpath.script:
(function () {
    var icon = "/kebi_website_custom/static/src/img/ts-favicon.svg";
    function setTianshuIcon() {
        var links = document.querySelectorAll('link[rel*="icon"]');
        for (var i = 0; i < links.length; i++) {
            links[i].href = icon;
            links[i].type = "image/svg+xml";
        }
        if (!links.length) {
            var link = document.createElement("link");
            link.rel = "icon";
            link.type = "image/svg+xml";
            link.href = icon;
            document.head.appendChild(link);
        }
    }
    setTianshuIcon();
    setTimeout(setTianshuIcon, 1000);
})();

t.script:
document.body.classList.add('kebi-home-body');
document.title = '天枢科技物流系统';
var f = document.querySelector('link[rel="icon"]') || document.createElement('link');
f.rel = 'icon';
f.type = 'image/svg+xml';
f.href = '/kebi_website_custom/static/src/img/ts-favicon.svg';
if (!f.parentNode) document.head.appendChild(f);

document.body.classList.add('kebi-login-body');
document.title = '天枢科技物流系统';
var f = document.querySelector('link[rel="icon"]') || document.createElement('link');
f.rel = 'icon'; f.type = 'image/svg+xml'; f.href = '/kebi_website_custom/static/src/img/ts-favicon.svg';
if (!f.parentNode) document.head.appendChild(f);
function cleanNav() {
    var sel = '.o_login_navbar,.o_login_header,#oe_snippets,.o_navbar_toggle,.o_menu_toggle,.o_header_toggle,.dropdown-toggle,.o_edit_menu_button,.o_menu_apps,.o_menu_systray,.o_wevent_editor_button,.o_menu_brand';
    var els = document.querySelectorAll(sel);
    for (var i = 0; i < els.length; i++) { els[i].style.display = 'none'; els[i].remove(); }
    // 删除所有fixed定位在顶部的元素(非自定义)
    var all = document.body.querySelectorAll('*');
    for (var j = 0; j < all.length; j++) {
        var cs = getComputedStyle(all[j]);
        if ((cs.position === 'fixed' && (cs.top === '0px' || parseInt(cs.top) < 10)) && all[j].offsetWidth < window.innerWidth && all[j].offsetHeight < 80 && !all[j].closest('.kebi-login-page')) {
            all[j].remove();
        }
    }
}
cleanNav();
setInterval(cleanNav, 500);
setTimeout(cleanNav, 2000);
